using System;using System.Collections.Generic;using System.IO;using System.IO.Pipes;using System.Linq;using System.Threading;using System.Xml;using MP1SkinStudio.Live;
class SceneProbe{
 static NamedPipeClientStream pipe;static string directory,epoch;static List<string> results=new List<string>();
 static XmlDocument Rpc(XmlDocument d){LiveWire.Write(pipe,d);var r=LiveWire.Read(pipe);if(r.DocumentElement.GetAttribute("ok")=="false")throw new Exception(r.DocumentElement.GetAttribute("message"));return r;}static XmlDocument Snapshot(){return Rpc(LiveWire.Document("snapshot"));}static void Hold(int n){for(int i=0;i<n;i++){Rpc(LiveWire.Document("ping"));Thread.Sleep(1000);}}static string V(XmlDocument d,int id){return d.SelectSingleNode("/live/control[@id='"+id+"']/value[@key='font']").InnerText;}static void Check(bool c,string n){if(!c)throw new Exception(n);results.Add("PASS "+n);Console.WriteLine("PASS "+n);}
 static XmlElement State(){for(int i=0;i<20;i++){try{var d=new XmlDocument{XmlResolver=null};using(var f=new FileStream(Path.Combine(directory,"special-state.xml"),FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))d.Load(f);return d.DocumentElement;}catch(IOException){Thread.Sleep(50);}}throw new Exception("No fixture observer state");}
 static XmlDocument Frame(XmlDocument baseline,string value){var d=LiveWire.Document("frame");LiveWire.Attr(d.DocumentElement,"epoch",epoch);foreach(int id in new[]{21201,21203,21204}){var c=LiveWire.Add(d.DocumentElement,"control");LiveWire.Attr(c,"token",baseline.SelectSingleNode("/live/control[@id='"+id+"']").Attributes["token"].Value);var f=LiveWire.Add(c,"set");LiveWire.Attr(f,"key","font");f.InnerText=value;}return d;}
 static int Main(string[] args){try{directory=args[0];Directory.CreateDirectory(args[1]);Environment.SetEnvironmentVariable("MP1_SKIN_STUDIO_LIVE_DIR",directory);var e=LiveEndpoint.Discover().Single();pipe=new NamedPipeClientStream(".",e.Pipe,PipeDirection.InOut,PipeOptions.Asynchronous);pipe.Connect(4000);var h=LiveWire.Document("hello");LiveWire.Attr(h.DocumentElement,"nonce",e.Nonce);Rpc(h);var a=LiveWire.Document("activate");LiveWire.Attr(a.DocumentElement,"window",90120);Rpc(a);Hold(2);var baseline=Snapshot();epoch=baseline.DocumentElement.GetAttribute("epoch");Check(baseline.DocumentElement.GetAttribute("fontDefinitions")=="private-v1"&&baseline.DocumentElement.GetAttribute("bridgeVersion")=="1.3.0.0","full MP advertises font definition previews in bridge 1.3");var original=State();int count=Int32.Parse(original.GetAttribute("fonts"));string family=original.GetAttribute("originalFamily"),size=original.GetAttribute("originalSize");var definition=new LiveFontDefinition{Family="Segoe UI",Height=28,Style=1};var frame=Frame(baseline,definition.ToWire());Rpc(frame);Hold(2);var changed=Snapshot();string preview=V(changed,21203);Check(preview.StartsWith("mp1studiofont_")&&V(changed,21201)==preview&&V(changed,21204)==preview,"label, checkbox and gallery use the same isolated preview font");Check(Int32.Parse(State().GetAttribute("fonts"))==count+1,"one preview definition appends one cache entry");Check(State().GetAttribute("originalSame")=="yes"&&State().GetAttribute("originalFamily")==family&&State().GetAttribute("originalSize")==size,"original registered MP font object and definition remain intact");Check(State().GetAttribute("items")=="6","font layout rebuilding retains all native gallery items");Check(changed.DocumentElement.GetAttribute("epoch")==epoch,"font preview keeps the same window and native controls");Console.WriteLine("HOLDING larger bold private font for 25 seconds");Hold(25);definition.Style=3;var italic=Frame(baseline,definition.ToWire());Rpc(italic);Hold(1);changed=Snapshot();string second=V(changed,21203);Check(second!=preview&&second.StartsWith("mp1studiofont_"),"font style has a distinct private cache identity");Rpc(italic);Hold(1);Check(Int32.Parse(State().GetAttribute("fonts"))==count+2,"repeated font definition reuses its private resource");var invalid=Frame(baseline,new LiveFontDefinition{Family="Studio Missing Family 77366",Height=28}.ToWire());LiveWire.Write(pipe,invalid);Check(LiveWire.Read(pipe).DocumentElement.GetAttribute("ok")=="false","unavailable Windows font family is rejected");Check(V(Snapshot(),21203)==second,"rejected font definition retains last valid preview");var empty=LiveWire.Document("frame");LiveWire.Attr(empty.DocumentElement,"epoch",epoch);Rpc(empty);Hold(1);changed=Snapshot();Check(new[]{21201,21203,21204}.All(id=>V(changed,id)==V(baseline,id)),"empty frame restores original fonts on all target control types");Rpc(frame);Rpc(LiveWire.Document("disconnect"));Check(State().GetAttribute("originalSame")=="yes"&&State().GetAttribute("items")=="6","disconnect preserves original registry and gallery data");Console.WriteLine(results.Count+" full-renderer font checks passed.");return 0;}catch(Exception ex){results.Add(ex.ToString());Console.Error.WriteLine(ex);return 1;}finally{if(pipe!=null)pipe.Dispose();Directory.CreateDirectory(args[1]);File.WriteAllLines(Path.Combine(args[1],"Results.txt"),results);}}
}
